import type { ReactElement } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps): ReactElement {
  return (
    <div className="status-message">
      <p role="status" className="status-message__text">
        {text}
      </p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
```

```css
.status-message {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75em;
  padding: 0.6em 0.9em;
  border: 1px solid var(--myelin);
  border-radius: 12px;
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  animation: status-message-in 200ms ease-out;
}

.status-message__text {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
}

.status-message__dismiss {
  font: inherit;
  font-size: 0.9em;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.25em 0.9em;
  cursor: pointer;
}

.status-message__dismiss:hover {
  background: var(--code-bg);
}

/* The focus outline comes from the global :focus-visible rule.
   This only adds a border colour on top of it. */
.status-message__dismiss:focus-visible {
  border-color: var(--myelin);
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message,
:root[data-motion="reduce"] .status-message__dismiss {
  animation: none;
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message,
  .status-message__dismiss {
    animation: none;
    transition: none;
  }
}
